const cut = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n - 3) + '...' : s; };
const who = { ap_guardian: 'AP Guardian', gl_sentinel: 'GL Sentinel' };
return $input.all().map(item => {
  const f = item.json;
  const content = [
    '**[' + String(f.risk).toUpperCase() + '] ' + (who[f.agent] || f.agent) + ': ' + cut(f.title, 200) + '**',
    'Condition: ' + cut(f.finding_condition, 900),
    'Recommendation: ' + cut(f.recommendation, 500),
    'Run: ' + f.run_id + '  Finding: ' + f.finding_id,
    '(proposed finding for a person to review; nothing has been changed or stopped)'
  ].join('\n');
  return { json: { finding_id: f.finding_id, content: cut(content, 1900) } };
});

const items = $input.all().map(i => i.json);
const cut = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n - 3) + '...' : s; };
const order = { high: 0, medium: 1, low: 2 };
items.sort((a, b) => (order[a.risk] - order[b.risk]));
const count = r => items.filter(f => f.risk === r).length;
const lines = items.map(f => '[' + String(f.risk).toUpperCase() + '] ' + f.agent + ': ' + cut(f.title, 160));
const text = [
  items.length + ' new proposed finding(s): ' + count('high') + ' high, ' + count('medium') + ' medium, ' + count('low') + ' low.',
  '',
  ...lines,
  '',
  'Full detail for each finding is posted in the Discord channel #fia-findings and stored in the findings table.',
  'These are proposals for a person to review. Nothing has been paid, stopped or changed.'
].join('\n');
return [{ json: {
  subject: 'FIA: ' + items.length + ' new proposed finding(s) (' + count('high') + ' high)',
  text: text,
  ids: items.map(f => f.finding_id).join('|')
} }];
